#include "scarlett_imports64.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace genesis;GuestMemory64 m;ScarlettImports64 h;assert(h.install(m));uint64_t r=0;auto a=h.registerImport("api-ms-win-crt-math-l1-1-0.dll","sqrt");std::array<uint8_t,16> fp{};double x=81;memcpy(fp.data(),&x,8);assert(a&&h.dispatch(a,m,0,r,0,0,0,0,0,&fp));memcpy(&x,fp.data(),8);assert(x==9);assert(h.registerImport("vcruntime140.dll","memcpy")==h.registerImport("VCRUNTIME140.dll","memcpy"));assert(h.registerImport("kernel32.dll","GetProcAddress")==h.registerImport("api-ms-win-core-libraryloader-l1-2-0.dll","GetProcAddress"));assert(!h.registerImport("kernel32.dll","nonexistent"));assert(m.map(0x10000,4096,3)==GuestMemory64::Fault::none);std::array<uint8_t,4> b{'a','b','c',0};assert(m.write(0x10000,b)==GuestMemory64::Fault::none);a=h.registerImport("api-ms-win-crt-string-l1-1-0.dll","__strncnt");assert(h.dispatch(a,m,0x10000,r,4)&&r==3);std::cout<<"V85B smoke tests passed\n";}
